// ==== Mobile Safari: off-screen floating button recovery ====
// The original code saves pixel coordinates. A coordinate saved on a taller
// screen can put the fixed button below the visible viewport on iPhone.
(function () {
    'use strict';
    function keepReactionButtonVisible() {
        const btn = document.getElementById('zgr-btn');
        if (!btn) return;

        const r = btn.getBoundingClientRect();
        const vv = window.visualViewport;
        const w = vv ? vv.width : window.innerWidth;
        const h = vv ? vv.height : window.innerHeight;
        const x = vv ? vv.offsetLeft : 0;
        const y = vv ? vv.offsetTop : 0;
        const margin = 8;
        const entirelyOutside = r.bottom <= y + margin ||
            r.top >= y + h - margin ||
            r.right <= x + margin ||
            r.left >= x + w - margin;

        if (!entirelyOutside) return;

        // Set a safe screen-relative position without changing any features
        // or the user's stored settings. The original drag handler still works.
        btn.style.position = 'fixed';
        btn.style.left = Math.max(x + margin, x + w - r.width - 16) + 'px';
        btn.style.top = Math.max(y + margin, y + h - r.height - 110) + 'px';
        btn.style.right = 'auto';
        btn.style.bottom = 'auto';
    }

    keepReactionButtonVisible();
    setInterval(keepReactionButtonVisible, 700);
    window.addEventListener('resize', keepReactionButtonVisible, { passive: true });
    if (window.visualViewport) {
        window.visualViewport.addEventListener('resize', keepReactionButtonVisible, { passive: true });
    }
})();


// ==== Comment instruction presets (Safari-compatible, no external libraries) ====
// This additive UI works with the original settings' native input/change listeners.
(function () {
    'use strict';
    const tonePresets = [
        ['디시 갤러리 말투', '디시인사이드 익명 갤러리 이용자처럼 자연스러운 반말을 사용한다. ㅋㅋ, ㅅㅂ, ㄹㅇ, ㅇㅇ, ~임, ~냐 등의 표현을 상황에 맞게 섞는다. 댓글마다 말투가 다르고, 짧고 투박한 반응을 우선한다. 억지 밈과 과장된 리액션은 피한다.'],
        ['여성향 덕질 커뮤니티', "여성향 덕질 커뮤니티 특유의 과몰입과 친근한 반말을 사용한다. 캐릭터의 말과 행동에 설레거나, 분노하거나, 안타까워하는 반응을 자연스럽게 섞는다. '아니 미친', '얘들아', '나만 이거 좋냐', '하...' 같은 표현을 적절히 사용한다. 모든 댓글을 호들갑스럽게 만들지는 않는다."],
        ['트위터(X) 오타쿠 말투', "트위터에서 캐릭터와 관계성을 덕질하는 사람들의 말투를 사용한다. 짧은 감탄, 혼잣말, 과몰입, 갑작스러운 감정 변화가 특징이다. '아', '아니', '잠만', '미치겠다' 같은 표현을 자연스럽게 활용한다. 문장을 일부러 끝맺지 않거나 여운을 남겨도 된다."],
        ['현실적인 익명 커뮤니티', '실제 익명 커뮤니티 댓글처럼 담백하고 자연스럽게 작성한다. 과도한 감탄, 억지 유행어, 인위적인 드립을 피한다. 일부 댓글은 짧고 무심하게, 일부는 진지하게 작성한다. 모든 사람이 상황에 깊이 몰입하지는 않으며 가벼운 농담이나 시큰둥한 반응도 섞는다.'],
        ['매운맛 커뮤니티', '필터 없는 익명 커뮤니티처럼 직설적이고 거친 반말을 사용한다. 욕설, 비꼼, 냉소, 조롱, 블랙유머를 상황에 맞게 섞는다. 캐릭터의 행동을 무조건 옹호하지 않으며 황당하거나 답답한 행동에는 날카롭게 반응한다. 모든 댓글을 욕설로 채우지 않고 자연스러운 강약을 유지한다.'],
        ['주접·과몰입', '캐릭터에게 진심으로 과몰입한 덕후들의 말투를 사용한다. 사소한 대사와 행동에도 의미를 부여하고 관계성에 열광한다. 감탄사, 반복 표현, 말줄임표, ㅋㅋㅋ, ㅠㅠ 등을 활용한다. 가끔은 말을 제대로 잇지 못하는 반응이나 짧은 비명을 섞는다.'],
        ['분석·궁예', "스토리를 주의 깊게 읽는 독자들의 댓글처럼 작성한다. 캐릭터의 심리, 대사의 숨은 의미, 관계 변화, 행동의 이유를 추측하는 반응이 중심이다. '~같음', '~아님?', '~일 수도', '내 생각엔' 같은 표현을 활용한다. 확인되지 않은 해석은 사실처럼 단정하지 않는다."],
        ['짧은 한마디 반응', "대부분의 댓글을 3~20자 내외의 짧고 즉각적인 반응으로 작성한다. '뭐임', '아 개웃겨', '와...', '이건 좀', 'ㄹㅇㅋㅋ', '헐'처럼 한마디만 남기는 댓글도 허용한다. 긴 설명이나 상황 요약은 최대한 피한다."]
    ];
    const extraPresets = [
        ['댓글끼리 의견 갈리기', '모든 댓글이 같은 의견을 내지 않도록 한다. 같은 상황에도 옹호, 비판, 의심, 농담 등 서로 다른 관점의 반응을 생성한다. 일부 댓글은 다른 댓글에 반박하거나 동조하는 것처럼 작성한다.'],
        ['캐릭터 팬덤 싸움', '댓글 작성자마다 선호하는 캐릭터와 관점이 다르게 느껴지도록 한다. 특정 캐릭터를 편드는 반응, 다른 캐릭터를 옹호하는 반응, 둘 다 비판하는 반응을 섞는다. 상황에 따라 팬덤 사이의 가벼운 논쟁이 생기도록 한다.'],
        ['캐릭터 관계성 집중', '캐릭터 사이의 미묘한 관계와 감정 변화에 집중한다. 호칭, 말투, 시선, 행동, 거리감 등의 변화를 포착해 반응한다. 로맨틱한 해석과 비로맨틱한 해석을 모두 허용하며, 실제로 나오지 않은 관계 설정은 만들어내지 않는다.'],
        ['복선·떡밥 분석', '작은 행동이나 대사에서 복선과 떡밥을 발견하려는 반응을 늘린다. 과거 대화와 연결하거나 앞으로의 전개를 추측할 수 있다. 단, 실제로 등장하지 않은 사건이나 설정을 과거에 있었던 일처럼 꾸며내지 않는다.'],
        ['웃긴 드립 위주', '진지한 상황에서도 웃긴 포인트를 발견하는 댓글을 섞는다. 상황에 맞는 드립, 비유, 말장난, 가벼운 놀림을 활용한다. 같은 농담을 반복하지 않으며 모든 댓글이 개그성일 필요는 없다.'],
        ['현실적인 비판 반응', '등장인물의 행동을 객관적으로 비판하거나 의문을 제기하는 댓글을 포함한다. 비상식적인 행동, 모순된 발언, 답답한 선택 등을 지적할 수 있다. 캐릭터가 매력적이라는 이유만으로 모든 행동을 정당화하지 않는다.'],
        ['실제 커뮤니티처럼 다양하게', '댓글 작성자들이 모두 같은 장면에 똑같이 집중하지 않도록 한다. 누군가는 대사에, 누군가는 캐릭터의 행동에, 누군가는 관계성에 반응한다. 가끔 사소한 디테일만 언급하거나 엉뚱한 부분에 꽂히는 댓글도 생성한다.'],
        ['원작 설정 철저히 준수', '반드시 실제 대화와 출력된 지문만을 근거로 반응한다. 등장하지 않은 사건, 대사, 관계, 과거사, 성격 설정을 새롭게 만들어내지 않는다. 실제 나온 대사만 큰따옴표("")로 인용한다. 추측과 확정된 사실을 명확히 구분한다.']
    ];

    function applyText(target, value) {
        target.value = value.slice(0, 10000);
        target.dispatchEvent(new Event('input', { bubbles: true }));
        target.dispatchEvent(new Event('change', { bubbles: true }));
    }
    function makeButton(label, onClick) {
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = label;
        Object.assign(button.style, {
            font: 'inherit', fontSize: '12px', fontWeight: '600',
            padding: '8px 10px', border: '1px solid #d8d8d8',
            background: '#fff', color: '#333', borderRadius: '9px',
            cursor: 'pointer', flex: '1 1 auto', minWidth: '0'
        });
        button.addEventListener('click', onClick);
        return button;
    }
    function attachPresets(selector, presets, name) {
        const area = document.querySelector(selector);
        if (!area || area.dataset.zgrPresetReady === 'yes') return;
        area.dataset.zgrPresetReady = 'yes';
        const panel = document.createElement('div');
        panel.className = 'zgr-preset-controls';
        Object.assign(panel.style, { margin: '8px 0 12px', display: 'flex', flexDirection: 'column', gap: '7px', maxWidth: '100%', boxSizing: 'border-box' });
        const select = document.createElement('select');
        select.setAttribute('aria-label', name + ' 예시 선택');
        Object.assign(select.style, {
            width: '100%', maxWidth: '100%', boxSizing: 'border-box',
            minHeight: '38px', padding: '7px 10px', font: 'inherit', fontSize: '13px',
            color: '#333', background: '#f8f8f8', border: '1px solid #ddd', borderRadius: '9px'
        });
        const initial = new Option('예시 선택 · 직접 입력도 가능', '');
        select.add(initial);
        presets.forEach(([label], index) => select.add(new Option(label, String(index))));
        const row = document.createElement('div');
        Object.assign(row.style, { display: 'flex', gap: '6px', flexWrap: 'wrap' });
        function selected() {
            if (select.value === '') return null;
            return presets[Number(select.value)]?.[1] || null;
        }
        row.appendChild(makeButton('선택 내용으로 바꾸기', () => {
            const value = selected();
            if (value === null) return;
            applyText(area, value);
        }));
        row.appendChild(makeButton('기존 내용에 추가', () => {
            const value = selected();
            if (value === null) return;
            const existing = area.value.trim();
            if (!existing.includes(value)) applyText(area, existing ? existing + '\n' + value : value);
        }));
        row.appendChild(makeButton('입력칸 비우기', () => applyText(area, '')));
        panel.appendChild(select);
        panel.appendChild(row);
        const help = document.createElement('div');
        help.textContent = '예시를 선택한 뒤 버튼을 누르세요. 아래 입력칸에서 직접 수정·입력할 수 있으며 자동 저장됩니다.';
        Object.assign(help.style, { fontSize: '11px', color: '#888', lineHeight: '1.5' });
        panel.appendChild(help);
        area.parentNode.insertBefore(panel, area);
    }
    function init() {
        attachPresets('#zgr-tone', tonePresets, '말투 지침');
        attachPresets('#zgr-extra', extraPresets, '추가 주문');
    }
    let scheduled = false;
    const observer = new MutationObserver(() => {
        if (scheduled) return;
        scheduled = true;
        requestAnimationFrame(() => { scheduled = false; init(); });
    });
    const start = () => {
        init();
        observer.observe(document.body, { childList: true, subtree: true });
    };
    if (document.body) start();
    else document.addEventListener('DOMContentLoaded', start, { once: true });
})();
